CastAuditCommand.signature:
db:cast-audit 
                            {--path=app/Models : Path to models} 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if cast mismatches are detected}

ColumnTypeAuditCommand.signature:
db:column-type-audit 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if inconsistent column types are detected}

DataDriftCommand.signature:
db:data-drift 
                            {--source= : Source connection to compare against} 
                            {--database= : The live database connection to check}
                            {--table= : Specific table to check}
                            {--fix : Interactively fix detected drifts}
                            {--limit=1000 : Maximum number of drift records to evaluate per table}
                            {--strict : Return a non-zero exit code if any drift is detected}
                            {--force : Force the operation to run when in production}

IndexAuditCommand.signature:
db:index-audit 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if missing foreign key indexes are found}

LegacyBridgeCommand.signature:
db:legacy-bridge 
                            {--tables= : Comma-separated list of tables (defaults to all)} 
                            {--database= : The database connection to use}
                            {--force : Overwrite existing generated artifact files}

LifecycleStatusCommand.signature:
db:lifecycle-status 
                            {--database= : The database connection to use}
                            {--format=table : Output format (table or json)}
                            {--strict : Return non-zero exit code if any check fails}

PiiScanCommand.signature:
db:pii-scan 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if potential PII columns are found}

RedundantIndexCommand.signature:
db:index-redundancy 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if redundant indexes are found}

SnapshotCommand.signature:
db:snapshot 
                            {name? : Optional name for the snapshot} 
                            {--database= : The database connection to use}
                            {--force : Overwrite existing snapshot file without prompt}

SnapshotDiffCommand.signature:
db:snapshot-diff 
                            {base : The baseline snapshot name} 
                            {target? : The snapshot to compare against (ignored if --live is used)}
                            {--live : Compare baseline snapshot against the live database}
                            {--database= : The database connection to use for live comparison}

SnapshotRestoreCommand.signature:
db:snapshot-restore 
                            {name : The snapshot file name to restore} 
                            {--database= : The database connection to use} 
                            {--recreate : Drop and recreate existing tables if safe (DESTRUCTIVE)}
                            {--dry-run : Preview planned actions without modifying the database}
                            {--force : Force the operation to run when in production}

SoftDeleteAuditCommand.signature:
db:soft-delete-audit 
                            {--path=app/Models : Path to models directory} 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if soft delete mismatches are found}

StandardizeIndexesCommand.signature:
db:standardize-indexes 
                            {--database= : The database connection to use}
                            {--dry-run : Only show what would be changed without applying}
                            {--force : Force the operation to run when in production}

TableConventionAuditCommand.signature:
db:convention-audit 
                            {--database= : The database connection to use}
                            {--strict : Return a non-zero exit code if naming convention violations are found}
